local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[405903]=b({e[23034],405903,9,77,296,"「しーっ！　レッパンズが起きちゃうのだ！　寝かしつけるのはゆずの役目なんだぞ。大変なんだからな！」",200059,2,"deco/character/you_SY",0,false,1,false,false,false,false,false,false,false,false,"0,-140,1","-120,0,1","-120,0,1",1976,914,380,1156,643,2053,2043,1156,643,2053,1221,false,false,false,false,false,false,false,false,false,false,false,false,"you_sy"},h)g[405904]=b({e[45057],405904,5,91,297,"「キュルルルゥー！　こ、こけちゃうぞー！　おまえ、助けてくれー！　……ふぅ。キュルル、まさか新年初日からこんな目に遭うなんてな。でもおまえの強力な正義の力によってゆずとゆずの晩ごはんが助かったのだ。」",200059,2,"deco/character/you_YD",0,false,false,false,1,false,false,false,false,false,"-140,0,1","80,-180,0.94","-100,0,1","-100,0,1","-120,0,1",false,false,false,false,false,false,false,false,false,false,false,2061,872,391,862,337,2157,2795,862,567,2157,"you_yd"},h)g[405905]=b({e[21034],405905,2,14,298,"「キュルルゥ、どうだ！　魔法に頼らずとも、水鉄砲合戦はゆずの方が一枚上手だったぞ！　……ち、ちょっと待つのだ！　二回戦の合図はまだ……ルール違反なのだ！　正義を蔑ろにするやつは、裁きを受けるがいいのだー！」",200059,2,"deco/character/you_YZ",0,false,false,false,false,false,false,false,false,false,false,"240,-250,1",1844,917,391,946,121,2423,2664,946,612,2423,false,1,3592,5000,1734,3050,8000,8000,5600,4333,13000,6666,2666,"you_yz"},h)g[405906]=b({e[17044],405906,17,71,299,"キュルルゥ……遅いのだ。ゆずの出番に間に合わなくなるとこだったぞ！\n……別に、おまえの励ましが欲しかったわけじゃないのだ。ほ、ほら、出番の前に会う約束してたし、おまえを約束も守れない奴にするわけにはいかないからな！",200059,2,"deco/character/you_BL",0,false,false,false,false,false,false,"0",0,1,3318,5000,1600,3856,2666,7333,9333,6666,14000,6666,2666,"you_bl"},h)g[406001]=b({e[17023],406001,false,136,300,false,200060,false,"deco/character/zekesi",false,60,1,false,false,false,-90,"0","0,420,1","-30,20,1","20,20,1",false,false,false,"-40,0,1",false,false,false,false,1849,838,390,1143,688,2159,2993,1143,688,2159,1105},h)g[406002]=b({e[17034],406002,1,4,301,"「む、んむむぅ！ ……っ、おい！\n今のは『今くわえてる布を取れ』じゃなくて、『そこの布をよこせ』って意味だ！\nどんだけ長く一緒にいると思ってんだ、目配せの意図くらい読めてもいいだろーが。\n……オイ、なに怒ってんだよ、俺様とつうかあの仲になんのがそんなに嫌か！？」",200060,1,"deco/character/zekesi_0",false,60,false,false,false,false,false,"0",1899,888,389,807,548,2470,2592,807,582,2470},h)g[406003]=b({e[24034],406003,11,127,302,"「俺様の刀に勝手に触んなっつっただろ！　いや、理由はそりゃ、触って怪我でもしたら大変なことになるからだよ。これでどついたりしたら、ピーピー泣いて面倒くせぇことになるに決まってら……ってマジでやるわけねぇだろが。」",200060,2,"deco/character/zekesi_YY",0,false,false,false,false,false,false,"0",false,"0,30,0.97","0,30,0.97","60,60,0.9","0,30,0.97","0,30,0.97","0,0,0.97",1792,851,380,632,422,3403,3138,883,540,2901},h)g[406004]=b({e[21034],406004,6,19,303,"「……ほら、手ぇ出せ。なんでって、引っ張ってやるために決まってんだろーが。日の光を照り返す雪と千本松、見てェだろ？　……別に、せっかくのハレの日だしな、テメェとこうして眺めんのも悪かねェ。そう思っただけだ！」",200060,2,"deco/character/zekesi_CJ",0,false,false,false,1,false,false,false,false,"160,0,1",false,"280,-80,0.95",1901,827,399,437,450,3118,2647,545,526,2902,false,1,1523,5000,800,985,5333,7166,7266,7333,15000,8000,10666},h)g[406101]=b({e[17023],406101,false,137,304,false,200061,false,"deco/character/beiyuanlili",false,60,1,false,false,false,43,"1.02999997138977","-30,70,1.02","0,0,1.03","0,0,1.03","0,0,1.03","0,0,1.03","0,0,1.03","0,0,1.03",false,"0,0,1.03",false,false,1862,859,387,1348,789,1926,2508,1348,789,1926,1024},h)g[406102]=b({e[17034],406102,1,4,305,"「もっと、こちらに。\n……そう、恐れずに、もっと。そのお顔に触れさせてくださいませ。\nなぜ、背を向けるのです？ いけません、きちんとわたくしの方を向いて。\nよくご覧になれましたか？\nあなた様の愛、そして欲望。……あなた様の、神様を。」",200061,1,"deco/character/beiyuanlili_0",false,60,1,false,false,false,false,"0",1847,895,386,137,false,3859,3884,616,587,2901,false,2,3594,5000,1743,2220,16000,16000,16000,12633,10000,16000,16000},h)g[406201]=b({e[17034],406201,false,138,306,false,200062,false,"deco/character/zhujingjiu",false,60,1,false,false,false,165,"0",1824,877,408,1436,808,1483,2415,1436,808,1483,1033},h)g[406202]=b({e[17034],406202,1,4,307,false,200062,1,"deco/character/zhujingjiu_0",false,60,1,false,false,false,false,"0",1819,861,408,1120,608,2205,2869,1120,608,2205,1217},h)g[406203]=b({e[23034],406203,998,99,308,false,200062,3,"deco/character/zhujingjiu_bunny",0,false,1,false,fals